/**
 * PHASE_5B P0-2: Razorpay checkout hook.
 * Loads script, creates order, opens checkout, verifies signature.
 * Auth: JWT-only via buildAuthHeaders(). x-user-id injected server-side by requireAuth.
 */
'use client';

import { useState, useCallback } from 'react';
import { buildAuthHeaders } from '@/lib/authHeaders';
import { API_BASE } from '@/lib/api';

function loadRazorpayScript(): Promise<boolean> {
  return new Promise((resolve) => {
    if (typeof window === 'undefined') { resolve(false); return; }
    if ((window as any).Razorpay) { resolve(true); return; }
    const script = document.createElement('script');
    script.src = 'https://checkout.razorpay.com/v1/checkout.js';
    script.onload = () => resolve(true);
    script.onerror = () => resolve(false);
    document.body.appendChild(script);
  });
}

export interface PaymentCallbacks {
  onSuccess?: (verifyData?: any) => void;
  /** called on error AND on cancel (cancelled=true on modal dismiss) */
  onError?: (message: string, cancelled?: boolean) => void;
}

export function useRazorpayCheckout() {
  const [isLoading, setIsLoading] = useState(false);

  const initiatePayment = useCallback(
    async (planType: string, callbacks: PaymentCallbacks = {}, promoCode?: string) => {
      if (isLoading) return;
      setIsLoading(true);

      try {
        // 1. Load Razorpay script
        const loaded = await loadRazorpayScript();
        if (!loaded) {
          callbacks.onError?.('Failed to load payment gateway. Check your connection and try again.');
          return;
        }

        // 2. Create order via backend
        const headers = buildAuthHeaders();
        const payload: { planType: string; promoCode?: string } = { planType };
        if (promoCode) payload.promoCode = promoCode;

        const orderRes = await fetch(`${API_BASE}/payments/create-order`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...headers },
          body: JSON.stringify(payload),
        });
        const orderData = await orderRes.json();

        if (!orderData.success) {
          callbacks.onError?.(orderData.message || 'Failed to create payment order. Please try again.');
          return;
        }

        const { orderId, razorpayKey, amount, currency = 'INR' } = orderData;

        // Extract user prefill for Razorpay Standard Checkout (critical for mobile UPI apps like GPay, PhonePe, Paytm)
        let prefill: { name?: string; email?: string; contact?: string } = {};
        try {
          const rawUser = localStorage.getItem('user');
          if (rawUser) {
            const parsed = JSON.parse(rawUser);
            prefill = {
              name: parsed.fullName || parsed.name || '',
              email: parsed.email || '',
              contact: parsed.mobileNumber || parsed.phone || '',
            };
          }
        } catch {}

        // 3. Open Razorpay checkout modal
        await new Promise<void>((resolve) => {
          const rzp = new (window as any).Razorpay({
            key: razorpayKey,
            amount,
            currency,
            order_id: orderId,
            name: 'Trayago',
            description: planType,
            prefill,
            theme: { color: '#3b82f6' },
            handler: async (response: {
              razorpay_order_id: string;
              razorpay_payment_id: string;
              razorpay_signature: string;
            }) => {
              // 4. Verify signature
              try {
                const verifyRes = await fetch(`${API_BASE}/payments/verify-signature`, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json', ...buildAuthHeaders() },
                  body: JSON.stringify({
                    razorpay_order_id: response.razorpay_order_id,
                    razorpay_payment_id: response.razorpay_payment_id,
                    razorpay_signature: response.razorpay_signature,
                  }),
                });
                const verifyData = await verifyRes.json();
                if (verifyData.success) {
                  // Synchronously update local user cache
                  try {
                    const rawUser = localStorage.getItem('user');
                    if (rawUser) {
                      const u = JSON.parse(rawUser);
                      u.planType = planType;
                      localStorage.setItem('user', JSON.stringify(u));
                    }
                    window.dispatchEvent(new Event('auth-change'));
                    window.dispatchEvent(new Event('storage'));
                  } catch {}
                  callbacks.onSuccess?.(verifyData);
                } else {
                  callbacks.onError?.(verifyData.message || 'Payment verification failed.');
                }
              } catch {
                callbacks.onError?.(
                  'Payment was received but verification failed. Contact support if amount was deducted.'
                );
              } finally {
                resolve();
              }
            },
            modal: {
              ondismiss: () => {
                callbacks.onError?.('Payment cancelled.', true);
                resolve();
              },
            },
          });
          rzp.open();
        });
      } catch (err: any) {
        callbacks.onError?.(err.message || 'Payment error. Please try again.');
      } finally {
        setIsLoading(false);
      }
    },
    [isLoading]
  );

  return { initiatePayment, isLoading };
}
